specimens.css:
/* 状态模拟：真实规则是 .imageItem:hover .remove / .remove:focus-visible（见 ComposerAttachments.module.css），
   触屏设备上由 @media (pointer: coarse) 常显。 */
.c1-imageItem.forceHover .c1-remove { opacity: 1; }

/* 状态模拟：真实规则是 .imageItem:hover .remove / .remove:focus-visible，
   以及 .card:hover .remove 与 .card:hover .name { padding-right: 18px }。 */
.c0-imageItem.forceHover .c0-remove { opacity: 1; }
.c2-card.forceHover .c2-remove { opacity: 1; }
.c2-card.forceHover .c2-name { padding-right: 18px; }

/* 静态快照：真实产品里 .mask 是 body 上的 fixed 全屏层（z-index:1000）。
   这里改成文档流内的相对定位，让 fixed 与 inset:0 失效但保留包含块；
   min-height 只是替掉视口高度，好让插图和文案仍有居中的空间。 */
.mask.snapshotStatic { position: relative; inset: auto; min-height: 260px; }

/* 状态模拟：真实规则是 .card:hover .remove { opacity: 1 } 与 .card:hover .name { padding-right: 18px }。 */
.c0-card.forceHover .c0-remove { opacity: 1; }
.c0-card.forceHover .c0-name { padding-right: 18px; }
